def find_least_multiple_of_30():
    from itertools import product
    n = 1
    while True:
        for digits in product(['0', '2'], repeat=n):
            if digits[-1] == '0' and digits[0] == '2':
                num_str = ''.join(digits)
                num = int(num_str)
                if num % 3 == 0:
                    return num
        n += 1

print(find_least_multiple_of_30())
```

